+/**
+ * Validates that a sync URL is a trusted Firebase URL.
+ * This prevents session data from being sent to attacker-controlled servers.
+ */
+export function isValidSyncURL(urlString: string): boolean {
+  try {
+    const url = new URL(urlString);
+    
+    // Allow localhost for development (with appropriate protocols)
+    if (url.hostname === 'localhost' || url.hostname === '127.0.0.1') {
+      return url.protocol === 'http:' || url.protocol === 'https:';
+    }
+    
+    // Validate the hostname is a Firebase domain
+    const hostname = url.hostname.toLowerCase();
+    
+    // List of trusted Firebase domains
+    const trustedDomains = [
+      'firebaseapp.com',
+      'firebase.google.com',
+      'googleapis.com',
+      'google.com'
+    ];
+    
+    // Check if the hostname ends with any trusted domain
+    return trustedDomains.some(domain => 
+      hostname === domain || hostname.endsWith('.' + domain)
+    ) && (
+      // Ensure secure protocol for production domains
+      url.protocol === 'https:' || hostname.includes('localhost')
+    );
+  } catch (e) {
+    // Invalid URL format
+    return false;
+  }
+}

