+package org.apache.streampipes.extensions.management.util;
+
+import java.net.InetAddress;
+import java.net.URI;
+import java.net.URL;
+import java.util.Arrays;
+import java.util.List;
+
+public class SsrfValidator {
+
+  // Default allowed repository hosts - should be configurable via application properties
+  private static final List<String> ALLOWED_REPOSITORY_HOSTS = Arrays.asList(
+      "repo.streampipes.org",
+      "github.com",
+      "raw.githubusercontent.com"
+  );
+
+  // Block internal/private IP addresses
+  private static final List<String> PRIVATE_NETWORK_PREFIXES = Arrays.asList(
+      "10.", "172.16.", "172.17.", "172.18.", "172.19.", "172.20.", 
+      "172.21.", "172.22.", "172.23.", "172.24.", "172.25.", "172.26.", 
+      "172.27.", "172.28.", "172.29.", "172.30.", "172.31.", "192.168.",
+      "127.", "169.254.", "::1", "0:0:0:0:0:0:0:1"
+  );
+
+  public static boolean isAllowedRepositoryUrl(String urlString) {
+    try {
+      URI uri = new URI(urlString).normalize();
+      
+      // Only allow HTTP and HTTPS protocols
+      String scheme = uri.getScheme();
+      if (scheme == null || (!scheme.equalsIgnoreCase("http") && !scheme.equalsIgnoreCase("https"))) {
+        return false;
+      }
+      
+      String host = uri.getHost();
+      if (host == null) {
+        return false;
+      }
+      
+      // Check against allowlist
+      if (!ALLOWED_REPOSITORY_HOSTS.contains(host.toLowerCase())) {
+        return false;
+      }
+      
+      // Additional safety check: resolve and block private IPs
+      InetAddress address = InetAddress.getByName(host);
+      return !isPrivateAddress(address.getHostAddress());
+    } catch (Exception e) {
+      return false;
+    }
+  }
+
+  private static boolean isPrivateAddress(String ipAddress) {
+    return PRIVATE_NETWORK_PREFIXES.stream().anyMatch(ipAddress::startsWith);
+  }
+}
